#!/usr/bin/env python3
# Patagonia trip ledger
# Walk the category subfolders, read each receipt, sum the amounts.
# ARS receipts are converted to USD using the rate looked up today.
import os

# xe.com mid-market rate (looked up today): 1 ARS = 0.00066528 USD
ARS_TO_USD = 0.00066528

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
CATEGORIES = ["lodging", "transport", "food"]


def parse_receipt(path):
    """Return (amount, currency) parsed from a receipt's Amount line."""
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line.lower().startswith("amount:"):
                parts = line.split()
                amount = float(parts[1].replace(",", ""))
                currency = parts[2].upper()
                return amount, currency
    return 0.0, "USD"


def to_usd(amount, currency):
    if currency == "ARS":
        return amount * ARS_TO_USD
    return amount


def main():
    for category in CATEGORIES:
        category_dir = os.path.join(BASE_DIR, category)
        total = 0.0
        if os.path.isdir(category_dir):
            for name in sorted(os.listdir(category_dir)):
                if name.endswith(".txt"):
                    amount, currency = parse_receipt(os.path.join(category_dir, name))
                    total += to_usd(amount, currency)
        print(f"{category}: ${total:.2f}")


if __name__ == "__main__":
    main()
EOF")

